      showCold: S.tab === 'cold', showUpload: S.tab === 'cold', openCold: () => set({ coldOpen: true, coldDone: false, cName: '', cPhone: '', cLang: '', cCm: '', cConsent: false, cErr: {}, cLangOpen: false }), openUpload: () => set({ upOpen: true, upMode: 'cold', upFile: '', upConsent: false, upErr: false }),
