      emptyIc: S.tab === 'cold', emptyIcUsers: S.tab !== 'cold',
      resetAll: () => set({ q: '', stage: '' }),
      openForm: () => set({ formOpen: true, formDone: false, fCurOpen: false }),
      openHelp: () => set({ helpOpen: true }), closeHelp: () => set({ helpOpen: false }),
